import{_ as n,a0 as p,w as d,s as g,I as a,x as s,a1 as l,A as t,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const V=JSON.parse('{"title":"Vim-plug：極簡 Vim 插件管理器 | LCTT x X-CMD","titleTemplate":false,"description":"Vim-plug：極簡 Vim 插件管理器 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Vim-plug：極簡 Vim 插件管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Vim-plug：極簡 Vim 插件管理器 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180601 Vim-plug - A Minimalist Vim Plugin Manager","title":"Vim-plug：極簡 Vim 插件管理器","tag":"201806","desc":""},"relativePath":"201806/20180601 Vim-plug - A Minimalist Vim Plugin Manager.md","filePath":"[post].md"}'),r={name:"201806/20180601 Vim-plug - A Minimalist Vim Plugin Manager.md"};function h(u,i,m,k,b,c){const e=p("Link");return d(),g("div",null,[i[20]||(i[20]=a("h1",{id:"vim-plug-極簡-vim-插件管理器",tabindex:"-1"},[s("Vim-plug：極簡 Vim 插件管理器 "),a("a",{class:"header-anchor",href:"#vim-plug-極簡-vim-插件管理器","aria-label":"Permalink to “Vim-plug：極簡 Vim 插件管理器”"},"​")],-1)),i[21]||(i[21]=a("p",null,[a("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/06/vim-plug-720x340.png",alt:""})],-1)),a("p",null,[i[1]||(i[1]=s("當沒有插件管理器時，Vim 用户必須手動下載 tarball 包形式的插件，並將它們解壓到 ",-1)),i[2]||(i[2]=a("code",null,"~/.vim",-1)),i[3]||(i[3]=s(" 目錄中。在少量插件的時候可以。但當他們安裝更多的插件時，就會變得一團糟。所有插件文件分散在單個目錄中，用户無法找到哪個文件屬於哪個插件。此外，他們無法找到他們應該刪除哪個文件來卸載插件。這時 Vim 插件管理器就可以派上用場。插件管理器將安裝插件的文件保存在單獨的目錄中，因此管理所有插件變得非常容易。我們幾個月前已經寫了關於 ",-1)),l(e,{href:"https://linux.cn/article-9416-1.html"},{default:t(()=>[...i[0]||(i[0]=[s("Vundle",-1)])]),_:1}),i[4]||(i[4]=s(" 的文章。今天，我們將看到又一個名為 “Vim-plug” 的 Vim 插件管理器。",-1))]),i[22]||(i[22]=o(`<p>Vim-plug 是一個自由、開源、速度非常快的、極簡的 vim 插件管理器。它可以並行地安裝或更新插件。你還可以回滾更新。它創建<ruby>淺層克隆<rt>shallow clone</rt></ruby>最小化磁盤空間使用和下載時間。它支持按需加載插件以加快啓動時間。其他值得注意的特性是支持分支/標籤/提交、post-update 鈎子、支持外部管理的插件等。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>安裝和使用起來非常容易。你只需打開終端並運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -fLo ~/.vim/autoload/plug.vim --create-dirs https://raw.githubusercontent.com/junegunn/vim-plug/master/plug.vim</span></span></code></pre></div><p>Neovim 用户可以使用以下命令安裝 Vim-plug：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -fLo ~/.config/nvim/autoload/plug.vim --create-dirs https://raw.githubusercontent.com/junegunn/vim-plug/master/plug.vim</span></span></code></pre></div><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><h4 id="安裝插件" tabindex="-1">安裝插件 <a class="header-anchor" href="#安裝插件" aria-label="Permalink to “安裝插件”">​</a></h4><p>要安裝插件，你必須如下所示首先在 Vim 配置文件中聲明它們。一般 Vim 的配置文件是 <code>~/.vimrc</code>，Neovim 的配置文件是 <code>~/.config/nvim/init.vim</code>。請記住，當你在配置文件中聲明插件時，列表應該以 <code>call plug#begin(PLUGIN_DIRECTORY)</code> 開始，並以 <code>plug#end()</code> 結束。</p><p>例如，我們安裝 “lightline.vim” 插件。為此，請在 <code>~/.vimrc</code> 的頂部添加以下行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>call plug#begin(&#39;~/.vim/plugged&#39;)</span></span>
<span class="line"><span>Plug &#39;itchyny/lightline.vim&#39;</span></span>
<span class="line"><span>call plug#end()</span></span></code></pre></div><p>在 vim 配置文件中添加上面的行後，通過輸入以下命令重新加載：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:source ~/.vimrc</span></span></code></pre></div><p>或者，只需重新加載 Vim 編輯器。</p><p>現在，打開 vim 編輯器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim</span></span></code></pre></div><p>使用以下命令檢查狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:PlugStatus</span></span></code></pre></div><p>然後輸入下面的命令，然後按回車鍵安裝之前在配置文件中聲明的插件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:PlugInstall</span></span></code></pre></div><h4 id="更新插件" tabindex="-1">更新插件 <a class="header-anchor" href="#更新插件" aria-label="Permalink to “更新插件”">​</a></h4><p>要更新插件，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:PlugUpdate</span></span></code></pre></div><p>更新插件後，按下 <code>d</code> 查看更改。或者，你可以之後輸入 <code>:PlugDiff</code>。</p><h4 id="審查插件" tabindex="-1">審查插件 <a class="header-anchor" href="#審查插件" aria-label="Permalink to “審查插件”">​</a></h4><p>有時，更新的插件可能有新的 bug 或無法正常工作。要解決這個問題，你可以簡單地回滾有問題的插件。輸入 <code>:PlugDiff</code> 命令，然後按回車鍵查看上次 <code>:PlugUpdate</code>的更改，並在每個段落上按 <code>X</code> 將每個插件回滾到更新前的前一個狀態。</p><h4 id="刪除插件" tabindex="-1">刪除插件 <a class="header-anchor" href="#刪除插件" aria-label="Permalink to “刪除插件”">​</a></h4><p>刪除一個插件刪除或註釋掉你以前在你的 vim 配置文件中添加的 <code>plug</code> 命令。然後，運行 <code>:source ~/.vimrc</code> 或重啓 Vim 編輯器。最後，運行以下命令卸載插件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:PlugClean</span></span></code></pre></div><p>該命令將刪除 vim 配置文件中所有未聲明的插件。</p><h4 id="升級-vim-plug" tabindex="-1">升級 Vim-plug <a class="header-anchor" href="#升級-vim-plug" aria-label="Permalink to “升級 Vim-plug”">​</a></h4><p>要升級vim-plug本身，請輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:PlugUpgrade</span></span></code></pre></div><p>如你所見，使用 Vim-plug 管理插件並不難。它簡化了插件管理。現在去找出你最喜歡的插件並使用 Vim-plug 來安裝它們。</p><p>就是這些了。我將很快在這裏發佈另一個有趣的話題。在此之前，請繼續關注我們。</p><p>乾杯!</p><hr>`,37)),a("p",null,[i[6]||(i[6]=s("via: ",-1)),l(e,{href:"https://www.ostechnix.com/vim-plug-a-minimalist-vim-plugin-manager/"},{default:t(()=>[...i[5]||(i[5]=[s("https://www.ostechnix.com/vim-plug-a-minimalist-vim-plugin-manager/",-1)])]),_:1})]),a("p",null,[i[11]||(i[11]=s("作者：",-1)),l(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...i[7]||(i[7]=[s("SK",-1)])]),_:1}),i[12]||(i[12]=s(" 選題：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...i[8]||(i[8]=[s("lujun9972",-1)])]),_:1}),i[13]||(i[13]=s(" 譯者：",-1)),l(e,{href:"https://github.com/geekpi"},{default:t(()=>[...i[9]||(i[9]=[s("geekpi",-1)])]),_:1}),i[14]||(i[14]=s(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:t(()=>[...i[10]||(i[10]=[s("wxy",-1)])]),_:1})]),a("p",null,[i[17]||(i[17]=s("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...i[15]||(i[15]=[s("LCTT",-1)])]),_:1}),i[18]||(i[18]=s(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:t(()=>[...i[16]||(i[16]=[s("Linux中國",-1)])]),_:1}),i[19]||(i[19]=s(" 榮譽推出",-1))])])}const C=n(r,[["render",h]]);export{V as __pageData,C as default};
